1: import { Observable, ObservableLike, SubscriptionObserver } from "observable-fns"
2: 
3: type OnFulfilled<T, Result = void> = (value: T) => Result
4: type OnRejected<Result = void> = (error: Error) => Result
5: 
6: type Initializer<T> = (observer: SubscriptionObserver<T>) => UnsubscribeFn | void
7: 
8: type Thenable<T> = { then: (onFulfilled?: (value: T) => any, onRejected?: (error: any) => any) => any }
9: 
10: type UnsubscribeFn = () => void
11: 
12: const doNothing = () => undefined
13: const returnInput = <T>(input: T): T => input
14: const runDeferred = (fn: () => void) => Promise.resolve().then(fn)
15: 
16: function fail(error: Error): never {
17:   throw error
18: }
19: 
20: function isThenable(thing: any): thing is Thenable<any> {
21:   return thing && typeof thing.then === "function"
22: }
