24: /**
25:  * Creates a hybrid, combining the APIs of an Observable and a Promise.
26:  *
27:  * It is used to proxy async process states when we are initially not sure
28:  * if that async process will yield values once (-> Promise) or multiple
29:  * times (-> Observable).
30:  *
31:  * Note that the observable promise inherits some of the observable's characteristics:
32:  * The `init` function will be called *once for every time anyone subscribes to it*.
33:  *
34:  * If this is undesired, derive a hot observable from it using `makeHot()` and
35:  * subscribe to that.
36:  */
37: export class ObservablePromise<T> extends Observable<T> implements Promise<T> {
38:   private initHasRun = false
39:   private fulfillmentCallbacks: Array<OnFulfilled<T>> = []
40:   private rejectionCallbacks: OnRejected[] = []
41: 
42:   private firstValue: T | undefined
43:   private firstValueSet = false
44:   private rejection: Error | undefined
45:   private state: "fulfilled" | "pending" | "rejected" = "pending"
46: 
47:   public readonly [Symbol.toStringTag]: "[object ObservablePromise]"
48: 
49:   constructor(init: Initializer<T>) {
50:     super((originalObserver: SubscriptionObserver<T>) => {
51:       // tslint:disable-next-line no-this-assignment
52:       const self = this
53:       const observer: SubscriptionObserver<T> = {
54:         ...originalObserver,
55:         complete() {
56:           originalObserver.complete()
57:           self.onCompletion()
58:         },
59:         error(error: Error) {
60:           originalObserver.error(error)
61:           self.onError(error)
62:         },
63:         next(value: T) {
64:           originalObserver.next(value)
65:           self.onNext(value)
66:         }
67:       }
68: 
69:       try {
70:         this.initHasRun = true
71:         return init(observer)
72:       } catch (error) {
73:         observer.error(error)
74:       }
75:     })
76:   }
77: 
78:   private onNext(value: T) {
79:     if (!this.firstValueSet) {
80:       this.firstValue = value
81:       this.firstValueSet = true
82:     }
83:   }
84: 
85:   private onError(error: Error) {
86:     this.state = "rejected"
87:     this.rejection = error
88: 
89:     for (const onRejected of this.rejectionCallbacks) {
90:       // Promisifying the call to turn errors into unhandled promise rejections
91:       // instead of them failing sync and cancelling the iteration
92:       runDeferred(() => onRejected(error))
93:     }
94:   }
95: 
96:   private onCompletion() {
97:     this.state = "fulfilled"
98: 
99:     for (const onFulfilled of this.fulfillmentCallbacks) {
100:       // Promisifying the call to turn errors into unhandled promise rejections
101:       // instead of them failing sync and cancelling the iteration
102:       runDeferred(() => onFulfilled(this.firstValue as T))
103:     }
104:   }
105: 
106:   public then<TResult1 = T, TResult2 = never>(
107:     onFulfilledRaw?: ((value: T) => TResult1 | PromiseLike<TResult1>) | undefined | null,
108:     onRejectedRaw?: ((reason: any) => TResult2 | PromiseLike<TResult2>) | undefined | null
109:   ): Promise<TResult1 | TResult2> {
110:     const onFulfilled: OnFulfilled<T, TResult1> = onFulfilledRaw || returnInput as any
111:     const onRejected = onRejectedRaw || fail
112:     let onRejectedCalled = false
113: 
114:     return new Promise<TResult1 | TResult2>((resolve, reject) => {
115:       const rejectionCallback = (error: Error) => {
116:         if (onRejectedCalled) return
117:         onRejectedCalled = true
118: 
119:         try {
120:           resolve(onRejected(error))
121:         } catch (anotherError) {
122:           reject(anotherError)
123:         }
124:       }
125:       const fulfillmentCallback = (value: T) => {
126:         try {
127:           resolve(onFulfilled(value))
128:         } catch (error) {
129:           rejectionCallback(error)
130:         }
131:       }
132:       if (!this.initHasRun) {
133:         this.subscribe({ error: rejectionCallback })
134:       }
135:       if (this.state === "fulfilled") {
136:         return resolve(onFulfilled(this.firstValue as T))
137:       }
138:       if (this.state === "rejected") {
139:         onRejectedCalled = true
140:         return resolve(onRejected(this.rejection as Error))
141:       }
142:       this.fulfillmentCallbacks.push(fulfillmentCallback)
143:       this.rejectionCallbacks.push(rejectionCallback)
144:     })
145:   }
