153:   public finally(onCompleted?: (() => void) | null | undefined) {
154:     const handler = onCompleted || doNothing
155:     return this.then(
156:       (value: T) => {
157:         handler()
158:         return value
159:       },
160:       () => handler()
161:     ) as Promise<T>
162:   }
