164:   public static from<T>(thing: Observable<T> | ObservableLike<T> | ArrayLike<T> | Thenable<T>): ObservablePromise<T> {
165:     if (isThenable(thing)) {
166:       return new ObservablePromise(observer => {
167:         const onFulfilled = (value: T) => {
168:           observer.next(value)
